import{_ as h,a8 as g,o as s,c as r,ah as o,a as t,a3 as a,K as e,L as n}from"./chunks/framework.BNwxUeRp.js";import"./chunks/theme.BC7t94LL.js";const G=JSON.parse('{"title":"AI全景概览","description":"","frontmatter":{"title":"AI全景概览","abstract":"AI 领域全景式概览，梳理人工智能从基础概念、发展脉络到大模型产业格局的整体框架，是知识库 AI 分类的总入口。","created":"2025-05-02T00:00:00.000Z","tags":["AI","人工智能导论","概览"],"type":"概念解释","related":["[[AI 应用核心范式-MOC]]"],"reference":"","category":["🤖 AI大模型","AI 产业与概览"]},"headers":[],"relativePath":"vault/Knowledge/AI/AI全景概览.md","filePath":"vault/Knowledge/AI/AI全景概览.md","lastUpdated":1790655645000}'),y={name:"vault/Knowledge/AI/AI全景概览.md"},p={tabindex:"0"},b={style:{"text-align":"left"}},Q={id:"mjx-6da5a22"},m={style:{"vertical-align":"-0.025ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.357ex",height:"1.025ex",role:"img",focusable:"false",viewBox:"0 -442 600 453","aria-hidden":"true"},u={id:"mjx-e326b46"},T={style:{"vertical-align":"-0.464ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.244ex",height:"2.059ex",role:"img",focusable:"false",viewBox:"0 -705 550 910","aria-hidden":"true"},w={id:"mjx-45c7fd1"},A={style:{"vertical-align":"-0.439ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.041ex",height:"1.439ex",role:"img",focusable:"false",viewBox:"0 -442 460 636","aria-hidden":"true"},I={id:"mjx-66a3543"},_={style:{"vertical-align":"-0.439ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.041ex",height:"1.439ex",role:"img",focusable:"false",viewBox:"0 -442 460 636","aria-hidden":"true"},c={id:"mjx-bfbecde"},M={style:{"vertical-align":"-0.439ex"},xmlns:"http://www.w3.org/2000/svg",width:"1.041ex",height:"1.439ex",role:"img",focusable:"false",viewBox:"0 -442 460 636","aria-hidden":"true"};function P(k,l,v,C,L,N){const i=g("mjx-assistive-mml"),d=g("mjx-container"),x=g("NolebaseGitContributors"),f=g("NolebaseGitChangelog");return s(),r("div",null,[l[23]||(l[23]=o('<h1 id="ai-全景概览" tabindex="-1">AI 全景概览 <a class="header-anchor" href="#ai-全景概览" aria-label="Permalink to “AI 全景概览”">​</a></h1><blockquote><p>来源：《人工智能导论：模型与算法》吴飞 著</p></blockquote><p>人工智能（Artificial Intelligence，AI）是以机器为载体所展示出来的人类智能，因此人工智能也被称为机器智能（Machine Intelligence）。</p><p>本章介绍人工智能的起源与发展，以及实现人工智能的五大核心方法：以符号主义为核心的逻辑推理、以问题求解为核心的探寻搜索、以数据驱动为核心的机器学习、以行为主义为核心的强化学习、以博弈对抗为核心的决策智能。</p><h2 id="人工智能的起源" tabindex="-1">人工智能的起源 <a class="header-anchor" href="#人工智能的起源" aria-label="Permalink to “人工智能的起源”">​</a></h2><p>1955年8月，John McCarthy、Marvin Minsky、Claude Shannon和Nathaniel Rochester四位学者在一份题为《人工智能达特茅斯夏季研究项目提案》的项目建议书中，首次使用了“Artificial Intelligence（人工智能）”这个术语。</p><p>1956年夏天，这批学者在达特茅斯学院召开研讨会，研究“让机器能像人那样认知、思考和学习的机器”，标志着人工智能正式登上人类历史舞台。</p><p><strong>该提案列举了人工智能需要研究的七个方面问题</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">编号</th><th style="text-align:left;">研究问题</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">自动计算模拟人脑高级功能</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">使用通用语言进行计算机编程以模仿人脑推理</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">神经元相互连接形成概念</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">对计算复杂性的度量</td></tr><tr><td style="text-align:left;">5</td><td style="text-align:left;">算法自我提升</td></tr><tr><td style="text-align:left;">6</td><td style="text-align:left;">算法的抽象能力</td></tr><tr><td style="text-align:left;">7</td><td style="text-align:left;">随机性与创造力</td></tr></tbody></table><p><strong>人工智能的定义</strong>：人工智能是以机器为载体所实现的人类智能或生物智能。</p><p>从人工智能的计算性和智能性角度，产生了两个核心问题：</p><ul><li><strong>承载计算之能的器械如何产生</strong>：推动了从手工计算到自动计算的迈进。</li><li><strong>如何利用计算之器来模拟人类智能</strong>：形成了符号逻辑（以推理为核心）、联结主义（以统计机器学习为手段）和行为学派（从环境交互中进行策略学习）等不同研究方法。</li></ul><h2 id="可计算载体-形式化与机械化" tabindex="-1">可计算载体：形式化与机械化 <a class="header-anchor" href="#可计算载体-形式化与机械化" aria-label="Permalink to “可计算载体：形式化与机械化”">​</a></h2><p>早期数学概念（如公理或定理）一般通过自然语言描述，但自然语言难以精确表达数学概念。因此，研究人员开始用符号来表达数学概念，即通过<strong>形式化语言</strong>来刻画数学概念。</p><h3 id="形式化系统" tabindex="-1">形式化系统 <a class="header-anchor" href="#形式化系统" aria-label="Permalink to “形式化系统”">​</a></h3><p>如果所有数学概念都可被形式化描述，给定一组推理规则后，就可从已有知识（公理、定理、命题等）出发，推导出新的知识。这样的系统被称为<strong>形式化系统</strong>。</p><p><strong>形式化系统需要具有的三个性质</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">性质</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>完备性</strong></td><td style="text-align:left;">所有能够被推导出来的知识，都可以从这个形式化系统推导出来</td></tr><tr><td style="text-align:left;"><strong>一致性</strong></td><td style="text-align:left;">所有可推导出来的知识不会同时推导出其否定，即形式化系统是自洽的、非矛盾的</td></tr><tr><td style="text-align:left;"><strong>可判定性</strong></td><td style="text-align:left;">对于形式化系统推导得到的任何知识，存在算法可在有限步内判定其为真或为假</td></tr></tbody></table><h3 id="哥德尔不完备定理" tabindex="-1">哥德尔不完备定理 <a class="header-anchor" href="#哥德尔不完备定理" aria-label="Permalink to “哥德尔不完备定理”">​</a></h3><ul><li>任何表达力足够强的（递归可枚举）形式系统都不可能同时具有一致性和完备性。</li><li>这个系统本身的一致性不能在系统内被证明。</li></ul><p>哥德尔不完备定理触及了<strong>不可计算</strong>这一难题，即有些数学问题是不可求解的（不可判定问题）。</p><h3 id="图灵机模型" tabindex="-1">图灵机模型 <a class="header-anchor" href="#图灵机模型" aria-label="Permalink to “图灵机模型”">​</a></h3><p>1937年，图灵发表了《论数字计算在决断难题中的应用》论文，提出了现代计算机的理论模型——<strong>图灵机模型</strong>。</p><p><strong>图灵机的组成</strong>：</p><ul><li>一条两端无限长的纸带，纸带上为可擦写小方格</li><li>程序控制器存储若干指令集</li><li>读写控制指针从左到右依次读入信息，触发指令执行操作，将计算结果写入纸带</li></ul><p><strong>邱奇-图灵论题</strong>：凡是可计算的函数都可以用图灵机计算。原始递归函数、λ-演算和图灵机在功能上是等效的。</p><table tabindex="0"><thead><tr><th style="text-align:left;">计算模型</th><th style="text-align:left;">特点</th><th style="text-align:left;">与人工智能的关系</th></tr></thead><tbody><tr><td style="text-align:left;">原始递归函数</td><td style="text-align:left;">从数学角度研究可计算问题</td><td style="text-align:left;">无法成为“机器载体”</td></tr><tr><td style="text-align:left;">λ-演算</td><td style="text-align:left;">从数理逻辑角度研究可计算问题</td><td style="text-align:left;">无法成为“机器载体”</td></tr><tr><td style="text-align:left;"><strong>图灵机</strong></td><td style="text-align:left;">通过机械化机制进行“计算”</td><td style="text-align:left;">成为现代计算机的理论模型，是人工智能的“机器载体”</td></tr></tbody></table><p>图灵机模型成为现代计算机的理论模型，推动了自动计算时代的到来。图灵也被誉为理论计算机之父，计算机界最高奖图灵奖即以他的名字命名。</p><h2 id="智能计算方法" tabindex="-1">智能计算方法 <a class="header-anchor" href="#智能计算方法" aria-label="Permalink to “智能计算方法”">​</a></h2><h3 id="五种智能计算方法对比" tabindex="-1">五种智能计算方法对比 <a class="header-anchor" href="#五种智能计算方法对比" aria-label="Permalink to “五种智能计算方法对比”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">方法</th><th style="text-align:left;">核心思想</th><th style="text-align:left;">代表性算法/方法</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>符号主义为核心的逻辑推理</strong></td><td style="text-align:left;">将概念符号化，从若干判断（前提）推出新判断（结论）</td><td style="text-align:left;">归纳推理、演绎推理、因果推理、专家系统</td></tr><tr><td style="text-align:left;"><strong>问题求解为核心的探寻搜索</strong></td><td style="text-align:left;">依据已有信息寻找满足约束条件的待求解问题答案</td><td style="text-align:left;">无信息搜索、启发式搜索、对抗搜索</td></tr><tr><td style="text-align:left;"><strong>数据驱动为核心的机器学习</strong></td><td style="text-align:left;">从数据出发，发现数据中承载语义的内在模式，用于识别和分类</td><td style="text-align:left;">监督学习、无监督学习、半监督学习、深度学习</td></tr><tr><td style="text-align:left;"><strong>行为主义为核心的强化学习</strong></td><td style="text-align:left;">根据环境提供的奖罚反馈学习最佳行动，平衡探索与利用</td><td style="text-align:left;">Q学习、深度强化学习（DRL）</td></tr><tr><td style="text-align:left;"><strong>博弈对抗为核心的决策智能</strong></td><td style="text-align:left;">多个主体为达到各自目标和利益采取的对抗行为，求取均衡解</td><td style="text-align:left;">纳什均衡、博弈策略求解、博弈规则设计</td></tr></tbody></table><h3 id="符号主义为核心的逻辑推理" tabindex="-1">符号主义为核心的逻辑推理 <a class="header-anchor" href="#符号主义为核心的逻辑推理" aria-label="Permalink to “符号主义为核心的逻辑推理”">​</a></h3><p>推理是进行思维模拟的基本形式之一，是从一个或几个已知的判断（前提）推出新判断（结论）的过程。在人工智能发展初期，脱胎于数理逻辑的<strong>符号主义人工智能</strong>是主流学派。</p><p><strong>核心思想</strong>：概念不再用自然语言描述，而是通过所定义的“符号”及符号之间的关系来表示，解决问题即构造一个证明来阐释其成立或不成立。</p><p><strong>三种主要推理方法</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">推理方法</th><th style="text-align:left;">基本逻辑</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>归纳推理</strong></td><td style="text-align:left;">从特殊到一般</td><td style="text-align:left;">从个别事实出发，推演出一般性知识作为结论</td></tr><tr><td style="text-align:left;"><strong>演绎推理</strong></td><td style="text-align:left;">从一般到特殊</td><td style="text-align:left;">从一般性前提出发，通过推导得出具体陈述或个别结论</td></tr><tr><td style="text-align:left;"><strong>因果推理</strong></td><td style="text-align:left;">因为A，所以B</td><td style="text-align:left;">判断事物间存在的原因和结果的关系，A是B的唯一前提</td></tr></tbody></table><p><strong>推理的三个层次</strong>（由易到难，Judea Pearl提出）：</p><ol><li><strong>关联</strong>：可直接从数据中计算得到的统计相关</li><li><strong>干预</strong>：无法直接从观测数据得到的关系</li><li><strong>反事实</strong>：某个事情已经发生，在相同环境中若此事不发生会带来怎样的新结果</li></ol><p><strong>应用</strong>：逻辑推理在人工智能领域的应用推动了<strong>专家系统</strong>的产生。专家系统存储问题求解所需的领域知识（事实、规则等），根据用户提交的问题应用推理规则得到解决方案。</p><h3 id="问题求解为核心的探寻搜索" tabindex="-1">问题求解为核心的探寻搜索 <a class="header-anchor" href="#问题求解为核心的探寻搜索" aria-label="Permalink to “问题求解为核心的探寻搜索”">​</a></h3><p><strong>搜索算法的分类</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">类型</th><th style="text-align:left;">说明</th><th style="text-align:left;">代表算法</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>无信息搜索</strong></td><td style="text-align:left;">盲目搜索方法，按照搜索策略扩展结点次序分类</td><td style="text-align:left;">广度优先搜索、深度优先搜索</td></tr><tr><td style="text-align:left;"><strong>有信息搜索</strong></td><td style="text-align:left;">启发式搜索，利用与所求解问题相关的辅助信息</td><td style="text-align:left;">贪婪最佳优先搜索、A*搜索</td></tr><tr><td style="text-align:left;"><strong>对抗搜索</strong></td><td style="text-align:left;">在竞争环境中，智能体之间通过竞争实现相反利益</td><td style="text-align:left;">最小最大搜索、Alpha-Beta剪枝搜索、蒙特卡洛树搜索</td></tr></tbody></table><h3 id="数据驱动为核心的机器学习" tabindex="-1">数据驱动为核心的机器学习 <a class="header-anchor" href="#数据驱动为核心的机器学习" aria-label="Permalink to “数据驱动为核心的机器学习”">​</a></h3><p>与逻辑推理直接定义公理、命题和规则不同，数据驱动方法从数据出发，从承载表达某一概念的数据中直接学习该概念所涉及的模式。</p><p><strong>核心思想</strong>：如果说逻辑推理可视为“从知识到知识”，那么机器学习完成了“从数据到知识”的过程。</p><p><strong>按数据利用方式的分类</strong>：</p>',46)),t("table",p,[l[9]||(l[9]=t("thead",null,[t("tr",null,[t("th",{style:{"text-align":"left"}},"类型"),t("th",{style:{"text-align":"left"}},"特点")])],-1)),t("tbody",null,[t("tr",null,[l[6]||(l[6]=t("td",{style:{"text-align":"left"}},[t("strong",null,"监督学习")],-1)),t("td",b,[l[4]||(l[4]=a("收集 ",-1)),t("span",Q,[e(d,{class:"MathJax",jax:"SVG",style:{position:"relative"}},{default:n(()=>[(s(),r("svg",m,[...l[0]||(l[0]=[t("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[t("g",{"data-mml-node":"math"},[t("g",{"data-mml-node":"mi"},[t("path",{"data-c":"1D45B",d:"M21 287Q22 293 24 303T36 341T56 388T89 425T135 442Q171 442 195 424T225 390T231 369Q231 367 232 367L243 378Q304 442 382 442Q436 442 469 415T503 336T465 179T427 52Q427 26 444 26Q450 26 453 27Q482 32 505 65T540 145Q542 153 560 153Q580 153 580 145Q580 144 576 130Q568 101 554 73T508 17T439 -10Q392 -10 371 17T350 73Q350 92 386 193T423 345Q423 404 379 404H374Q288 404 229 303L222 291L189 157Q156 26 151 16Q138 -11 108 -11Q95 -11 87 -5T76 7T74 17Q74 30 112 180T152 343Q153 348 153 366Q153 405 129 405Q91 405 66 305Q60 285 60 284Q58 278 41 278H27Q21 284 21 287Z"})])])],-1)])])),e(i,{unselectable:"on",display:"inline"},{default:n(()=>[...l[1]||(l[1]=[t("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[t("mi",null,"n")],-1)])]),_:1})]),_:1})]),l[5]||(l[5]=a(" 个标注数据作为训练集，从假设空间中学习最优映射函数 ",-1)),t("span",u,[e(d,{class:"MathJax",jax:"SVG",style:{position:"relative"}},{default:n(()=>[(s(),r("svg",T,[...l[2]||(l[2]=[t("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[t("g",{"data-mml-node":"math"},[t("g",{"data-mml-node":"mi"},[t("path",{"data-c":"1D453",d:"M118 -162Q120 -162 124 -164T135 -167T147 -168Q160 -168 171 -155T187 -126Q197 -99 221 27T267 267T289 382V385H242Q195 385 192 387Q188 390 188 397L195 425Q197 430 203 430T250 431Q298 431 298 432Q298 434 307 482T319 540Q356 705 465 705Q502 703 526 683T550 630Q550 594 529 578T487 561Q443 561 443 603Q443 622 454 636T478 657L487 662Q471 668 457 668Q445 668 434 658T419 630Q412 601 403 552T387 469T380 433Q380 431 435 431Q480 431 487 430T498 424Q499 420 496 407T491 391Q489 386 482 386T428 385H372L349 263Q301 15 282 -47Q255 -132 212 -173Q175 -205 139 -205Q107 -205 81 -186T55 -132Q55 -95 76 -78T118 -61Q162 -61 162 -103Q162 -122 151 -136T127 -157L118 -162Z"})])])],-1)])])),e(i,{unselectable:"on",display:"inline"},{default:n(()=>[...l[3]||(l[3]=[t("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[t("mi",null,"f")],-1)])]),_:1})]),_:1})])])]),l[7]||(l[7]=t("tr",null,[t("td",{style:{"text-align":"left"}},[t("strong",null,"无监督学习")]),t("td",{style:{"text-align":"left"}},"数据本身不包含标注信息")],-1)),l[8]||(l[8]=t("tr",null,[t("td",{style:{"text-align":"left"}},[t("strong",null,"半监督学习")]),t("td",{style:{"text-align":"left"}},"一部分数据有标注信息，一部分没有")],-1))])]),l[24]||(l[24]=o('<p><strong>深度学习</strong>作为联结主义方法的代表，通过构造逐层抽象的“端到端”机制来学习隐含在数据内部的模式，得到更强表达力和泛化能力的特征表达。</p><p><strong>理论基础</strong>：赫布理论指出“神经元之间持续重复经验刺激可导致突触传递效能增加”，为联结主义人工智能研究提供了认知神经心理学基础。</p><h3 id="行为主义为核心的强化学习" tabindex="-1">行为主义为核心的强化学习 <a class="header-anchor" href="#行为主义为核心的强化学习" aria-label="Permalink to “行为主义为核心的强化学习”">​</a></h3><p>强化学习赋予智能体<strong>自监督学习能力</strong>，使其能够自主与环境交互，做出序列决策，完成序列化形式的任务。</p><p><strong>核心机制</strong>：</p><ul><li>智能体通过与环境的交互，根据环境给出的<strong>奖惩反馈</strong>来不断改进策略</li><li>运用 <strong>“尝试-试错”</strong> 与平衡 <strong>“探索与利用”</strong> 等机制不断进步</li><li>目标是获得最大的<strong>累积奖惩</strong></li></ul><p><strong>监督学习、无监督学习与强化学习的差异</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">监督学习</th><th style="text-align:left;">无监督学习</th><th style="text-align:left;">强化学习</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>学习依据</strong></td><td style="text-align:left;">基于监督信息</td><td style="text-align:left;">基于对数据结构的假设</td><td style="text-align:left;">基于评价（evaluative）</td></tr><tr><td style="text-align:left;"><strong>数据来源</strong></td><td style="text-align:left;">一次性给定（含标注信息）</td><td style="text-align:left;">一次性给定（无标注信息）</td><td style="text-align:left;">在序列交互中产生，序列结束才反馈明确奖惩值</td></tr><tr><td style="text-align:left;"><strong>决策过程</strong></td><td style="text-align:left;">根据标注信息做出单步静态决策</td><td style="text-align:left;">无</td><td style="text-align:left;">根据环境给出的滞后回报做出序列决策</td></tr><tr><td style="text-align:left;"><strong>学习目标</strong></td><td style="text-align:left;">样本空间到高级语义空间的映射</td><td style="text-align:left;">同一类数据的分布模式</td><td style="text-align:left;">选择能获取最大收益的状态到动作的映射</td></tr></tbody></table>',8)),t("p",null,[l[16]||(l[16]=t("strong",null,"Q学习",-1)),l[17]||(l[17]=a("：学习智能体的 ",-1)),t("span",w,[e(d,{class:"MathJax",jax:"SVG",style:{position:"relative"}},{default:n(()=>[(s(),r("svg",A,[...l[10]||(l[10]=[t("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[t("g",{"data-mml-node":"math"},[t("g",{"data-mml-node":"mi"},[t("path",{"data-c":"1D45E",d:"M33 157Q33 258 109 349T280 441Q340 441 372 389Q373 390 377 395T388 406T404 418Q438 442 450 442Q454 442 457 439T460 434Q460 425 391 149Q320 -135 320 -139Q320 -147 365 -148H390Q396 -156 396 -157T393 -175Q389 -188 383 -194H370Q339 -192 262 -192Q234 -192 211 -192T174 -192T157 -193Q143 -193 143 -185Q143 -182 145 -170Q149 -154 152 -151T172 -148Q220 -148 230 -141Q238 -136 258 -53T279 32Q279 33 272 29Q224 -10 172 -10Q117 -10 75 30T33 157ZM352 326Q329 405 277 405Q242 405 210 374T160 293Q131 214 119 129Q119 126 119 118T118 106Q118 61 136 44T179 26Q233 26 290 98L298 109L352 326Z"})])])],-1)])])),e(i,{unselectable:"on",display:"inline"},{default:n(()=>[...l[11]||(l[11]=[t("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[t("mi",null,"q")],-1)])]),_:1})]),_:1})]),l[18]||(l[18]=a(" 函数，记录某个状态下采取某一动作所能够收到的奖励值。将 ",-1)),t("span",I,[e(d,{class:"MathJax",jax:"SVG",style:{position:"relative"}},{default:n(()=>[(s(),r("svg",_,[...l[12]||(l[12]=[t("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[t("g",{"data-mml-node":"math"},[t("g",{"data-mml-node":"mi"},[t("path",{"data-c":"1D45E",d:"M33 157Q33 258 109 349T280 441Q340 441 372 389Q373 390 377 395T388 406T404 418Q438 442 450 442Q454 442 457 439T460 434Q460 425 391 149Q320 -135 320 -139Q320 -147 365 -148H390Q396 -156 396 -157T393 -175Q389 -188 383 -194H370Q339 -192 262 -192Q234 -192 211 -192T174 -192T157 -193Q143 -193 143 -185Q143 -182 145 -170Q149 -154 152 -151T172 -148Q220 -148 230 -141Q238 -136 258 -53T279 32Q279 33 272 29Q224 -10 172 -10Q117 -10 75 30T33 157ZM352 326Q329 405 277 405Q242 405 210 374T160 293Q131 214 119 129Q119 126 119 118T118 106Q118 61 136 44T179 26Q233 26 290 98L298 109L352 326Z"})])])],-1)])])),e(i,{unselectable:"on",display:"inline"},{default:n(()=>[...l[13]||(l[13]=[t("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[t("mi",null,"q")],-1)])]),_:1})]),_:1})]),l[19]||(l[19]=a(" 函数参数化，用神经网络来拟合 ",-1)),t("span",c,[e(d,{class:"MathJax",jax:"SVG",style:{position:"relative"}},{default:n(()=>[(s(),r("svg",M,[...l[14]||(l[14]=[t("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[t("g",{"data-mml-node":"math"},[t("g",{"data-mml-node":"mi"},[t("path",{"data-c":"1D45E",d:"M33 157Q33 258 109 349T280 441Q340 441 372 389Q373 390 377 395T388 406T404 418Q438 442 450 442Q454 442 457 439T460 434Q460 425 391 149Q320 -135 320 -139Q320 -147 365 -148H390Q396 -156 396 -157T393 -175Q389 -188 383 -194H370Q339 -192 262 -192Q234 -192 211 -192T174 -192T157 -193Q143 -193 143 -185Q143 -182 145 -170Q149 -154 152 -151T172 -148Q220 -148 230 -141Q238 -136 258 -53T279 32Q279 33 272 29Q224 -10 172 -10Q117 -10 75 30T33 157ZM352 326Q329 405 277 405Q242 405 210 374T160 293Q131 214 119 129Q119 126 119 118T118 106Q118 61 136 44T179 26Q233 26 290 98L298 109L352 326Z"})])])],-1)])])),e(i,{unselectable:"on",display:"inline"},{default:n(()=>[...l[15]||(l[15]=[t("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[t("mi",null,"q")],-1)])]),_:1})]),_:1})]),l[20]||(l[20]=a(" 函数，即可形成",-1)),l[21]||(l[21]=t("strong",null,"深度强化学习",-1)),l[22]||(l[22]=a("。",-1))]),l[25]||(l[25]=o('<h3 id="博弈对抗为核心的决策智能" tabindex="-1">博弈对抗为核心的决策智能 <a class="header-anchor" href="#博弈对抗为核心的决策智能" aria-label="Permalink to “博弈对抗为核心的决策智能”">​</a></h3><p>博弈行为是多个带有相互竞争性质的主体，为达到各自目标和利益，采取的带有对抗性质的行为，即“两害相权取其轻，两利相权取其重”。</p><p><strong>核心转变</strong>：推动机器学习从“数据拟合”过程中以“求取最优解”为核心，向博弈对抗过程中“求取均衡解”为核心的转变。</p><p><strong>重要概念</strong>：</p><ul><li><strong>博弈论</strong>：研究博弈行为中最优的对抗策略及其稳定局势</li><li><strong>纳什均衡</strong>：约翰·纳什于1950年提出，非合作博弈的均衡解一定存在</li></ul><p><strong>五种方法各有优劣</strong>：</p><ul><li>逻辑推理方法解释性强，但难以拓展</li><li>搜索方法从已有答案中查找，但受困于机械式匹配</li><li>数据驱动模型擅于预测识别，但过程难以理解</li><li>强化学习能探索未知空间，但依赖于策略学习</li><li>博弈对抗在完全信息条件下表现优良，但难以找到非完全信息条件下的通用框架</li></ul><p>因此，需要有机协调知识指导下演绎、数据驱动中归纳、行为强化内规划等不同方法，建立知识、数据和反馈于一体的人工智能理论和模型。</p><h2 id="全书内容概览" tabindex="-1">全书内容概览 <a class="header-anchor" href="#全书内容概览" aria-label="Permalink to “全书内容概览”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">章节</th><th style="text-align:left;">内容</th><th style="text-align:left;">核心知识点</th></tr></thead><tbody><tr><td style="text-align:left;">第2章</td><td style="text-align:left;">逻辑与推理</td><td style="text-align:left;">命题逻辑、谓词逻辑、知识图谱推理、因果推理</td></tr><tr><td style="text-align:left;">第3章</td><td style="text-align:left;">搜索求解</td><td style="text-align:left;">启发式搜索、对抗搜索、蒙特卡洛树搜索</td></tr><tr><td style="text-align:left;">第4章</td><td style="text-align:left;">机器学习：监督学习</td><td style="text-align:left;">回归分析、决策树、LDA、AdaBoosting、SVM</td></tr><tr><td style="text-align:left;">第5章</td><td style="text-align:left;">统计机器学习：无监督学习</td><td style="text-align:left;">K-means、PCA、特征人脸、LSA、EM算法</td></tr><tr><td style="text-align:left;">第6章</td><td style="text-align:left;">深度学习</td><td style="text-align:left;">前馈神经网络、CNN、RNN、GAN</td></tr><tr><td style="text-align:left;">第7章</td><td style="text-align:left;">强化学习</td><td style="text-align:left;">MDP、策略优化、Q学习、深度强化学习</td></tr><tr><td style="text-align:left;">第8章</td><td style="text-align:left;">人工智能博弈</td><td style="text-align:left;">纳什均衡、博弈策略求解、博弈规则设计</td></tr><tr><td style="text-align:left;">第9章</td><td style="text-align:left;">人工智能未来发展和趋势</td><td style="text-align:left;">类脑计算、AutoML、模型压缩、AI芯片、伦理</td></tr></tbody></table><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h2><p>1955年提出人工智能概念时，其“初心”是“仿真”人类行为。经过长期发展，已形成五大核心方法：逻辑推理、搜索求解、机器学习、强化学习和博弈对抗。</p><p><strong>当前人工智能的局限性</strong>：</p><ul><li>现有算法或系统属于“领域人工智能”或“弱人工智能”的研究范畴</li><li>与具有自我学习、直觉推理、自适应和能力迁移等特点的<strong>通用人工智能</strong>仍存在差距</li><li>图灵机模型所能完成的可计算任务都是可递归的，而人类面临的许多现实问题具有不确定性、脆弱性和开放性等特点</li></ul><p><strong>未来方向</strong>：需要将人类智能与机器智能进行有效协同，形成<strong>混合-增强智能</strong>形态，这是发展人工智能的可行之道。正如大卫·希尔伯特所言：“我们必须知道，我们必将知道。”这种“可认知”乐观主义态度将鼓舞人工智能研究者和实践者不断探索。</p><hr><p>人工智能作为引领新一轮科技革命和产业变革的战略性技术，正在深刻改变人类社会。本章从类脑计算、自动化机器学习、神经网络压缩、人工智能芯片、量子机器学习、人工智能伦理与治理、人工智能算法开发框架等方面，简要总结人工智能的未来发展方向和趋势。</p><h2 id="类脑计算" tabindex="-1">类脑计算 <a class="header-anchor" href="#类脑计算" aria-label="Permalink to “类脑计算”">​</a></h2><p>类脑计算（Brain-inspired Computing）是受脑功能和脑神经网络连接机制启发的一种计算架构，旨在以神经形态计算的模式来部分模拟大脑功能，在结构层次和器件层次逼近人脑。</p><p><strong>研究层次</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">层次</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>微观（基因/分子）</strong></td><td style="text-align:left;">研究神经元的分子生物学基础</td></tr><tr><td style="text-align:left;"><strong>介观（神经环路）</strong></td><td style="text-align:left;">研究神经元之间的连接通路和网络结构</td></tr><tr><td style="text-align:left;"><strong>宏观（脑区/认知）</strong></td><td style="text-align:left;">研究脑区和认知功能的关系</td></tr></tbody></table><p><strong>研究方向</strong>：</p><ul><li><strong>神经形态计算</strong>：采用脉冲神经网络（SNN）模拟生物神经元的脉冲发放机制，实现低功耗、高能效的计算</li><li><strong>存算一体</strong>：打破传统冯·诺依曼架构中计算与存储分离的瓶颈，实现类脑的存算融合</li><li><strong>神经形态芯片</strong>：研制专门支持脉冲神经网络和类脑计算的硬件，如 IBM 的 TrueNorth、英特尔的 Loihi</li></ul><p><strong>挑战</strong>：</p><ul><li>对大脑工作机制的理解仍然有限</li><li>神经科学和计算科学的交叉融合不够深入</li><li>大规模类脑系统的设计与实现存在技术瓶颈</li></ul><h2 id="自动化机器学习-automl" tabindex="-1">自动化机器学习（AutoML） <a class="header-anchor" href="#自动化机器学习-automl" aria-label="Permalink to “自动化机器学习（AutoML）”">​</a></h2><p><strong>自动化覆盖的环节</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">环节</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>数据预处理</strong></td><td style="text-align:left;">自动化数据清洗、特征选择、特征工程</td></tr><tr><td style="text-align:left;"><strong>模型选择</strong></td><td style="text-align:left;">根据任务自动选择合适的算法和模型架构</td></tr><tr><td style="text-align:left;"><strong>超参数优化</strong></td><td style="text-align:left;">自动搜索最优的超参数组合（如学习率、网络深度等）</td></tr><tr><td style="text-align:left;"><strong>神经架构搜索（NAS）</strong></td><td style="text-align:left;">自动搜索最优的神经网络结构</td></tr></tbody></table><p><strong>核心技术</strong>：</p><ul><li><strong>强化学习</strong>：将架构搜索建模为序列决策问题</li><li><strong>进化算法</strong>：模拟生物进化过程，通过交叉、变异选择更优的架构</li><li><strong>梯度优化</strong>：将架构参数松弛为连续变量，使用梯度下降直接优化</li></ul><p><strong>意义</strong>：</p><ul><li>降低人工智能应用门槛，使非AI专家也能高效使用</li><li>提升模型设计效率，减少人工试错</li><li>发现人工难以想到的新型网络结构</li></ul><h2 id="神经网络模型压缩" tabindex="-1">神经网络模型压缩 <a class="header-anchor" href="#神经网络模型压缩" aria-label="Permalink to “神经网络模型压缩”">​</a></h2><p>深度学习模型的参数量和计算量巨大，难以在资源受限的边缘设备上部署。模型压缩旨在<strong>减小模型尺寸、加速推理速度</strong>，同时尽可能保持模型精度。</p><p><strong>主要技术路线</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">方法</th><th style="text-align:left;">核心思想</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>剪枝（Pruning）</strong></td><td style="text-align:left;">移除对模型输出贡献较小的冗余权重或神经元</td></tr><tr><td style="text-align:left;"><strong>量化（Quantization）</strong></td><td style="text-align:left;">将32位浮点参数映射为低精度整数（如8位），减少存储和计算开销</td></tr><tr><td style="text-align:left;"><strong>知识蒸馏（Knowledge Distillation）</strong></td><td style="text-align:left;">使用大模型（教师网络）的输出指导小模型（学生网络）训练，使小模型学到相同的知识</td></tr><tr><td style="text-align:left;"><strong>低秩分解（Low-Rank Decomposition）</strong></td><td style="text-align:left;">对大规模权值矩阵进行低秩近似分解，减少参数量</td></tr><tr><td style="text-align:left;"><strong>紧凑网络设计</strong></td><td style="text-align:left;">设计新颖的轻量级网络结构（如MobileNet、ShuffleNet），在源头减少参数</td></tr></tbody></table><p><strong>应用场景</strong>：</p><ul><li>智能手机、IoT设备的端侧部署</li><li>实时视频分析和语音识别</li><li>云端推理服务的成本优化</li></ul><h2 id="人工智能芯片" tabindex="-1">人工智能芯片 <a class="header-anchor" href="#人工智能芯片" aria-label="Permalink to “人工智能芯片”">​</a></h2><p><strong>传统芯片的局限性</strong>：</p><ul><li><strong>CPU</strong>：通用性强但并行计算能力有限</li><li><strong>GPU</strong>：并行能力强，适合深度学习训练，但功耗较高</li></ul><p><strong>AI芯片设计目标</strong>：</p><ul><li>高吞吐量（支持大规模矩阵运算）</li><li>低功耗（适用于端侧设备）</li><li>灵活性（支持多样化神经网络结构）</li></ul><p><strong>代表性AI芯片</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">芯片</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Google TPU</strong></td><td style="text-align:left;">专为TensorFlow优化的张量处理器</td></tr><tr><td style="text-align:left;"><strong>NVIDIA A100/H100</strong></td><td style="text-align:left;">面向数据中心的多功能AI加速卡</td></tr><tr><td style="text-align:left;"><strong>华为昇腾（Ascend）</strong></td><td style="text-align:left;">支持端、边、云全场景</td></tr><tr><td style="text-align:left;"><strong>寒武纪</strong></td><td style="text-align:left;">专注于深度学习处理的专用芯片</td></tr><tr><td style="text-align:left;"><strong>FPGA加速器</strong></td><td style="text-align:left;">可编程逻辑门阵列，灵活但开发门槛较高</td></tr></tbody></table><p><strong>发展趋势</strong>：存算一体芯片、光计算芯片、量子计算芯片等新一代计算范式正在探索中。</p><h2 id="量子机器学习" tabindex="-1">量子机器学习 <a class="header-anchor" href="#量子机器学习" aria-label="Permalink to “量子机器学习”">​</a></h2><p>量子机器学习是<strong>量子计算与机器学习</strong>的交叉研究领域，旨在利用量子计算的优势（叠加态、纠缠、干涉等量子效应）来加速或改进机器学习算法的训练和推理效率。</p><p><strong>核心研究方向</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">方向</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>量子加速学习</strong></td><td style="text-align:left;">利用量子算法加速经典机器学习中的线性代数运算或参数优化过程</td></tr><tr><td style="text-align:left;"><strong>量子神经网络</strong></td><td style="text-align:left;">构造基于量子比特和量子线路的神经网络模型，探索新的学习范式</td></tr><tr><td style="text-align:left;"><strong>量子增强特征空间</strong></td><td style="text-align:left;">利用量子态在高维希尔伯特空间中编码数据，实现经典方法难以获得的非线性特征映射</td></tr><tr><td style="text-align:left;"><strong>量子采样与生成模型</strong></td><td style="text-align:left;">利用量子退火或量子随机游走进行采样，加速生成模型训练</td></tr></tbody></table><p><strong>理论基础</strong>：</p><ul><li>利用了量子叠加态进行并行态的计算</li><li>通过量子纠缠建立数据间的量子关联模式</li><li>量子干涉效应放大正确路径的概率幅</li></ul><p><strong>现状与挑战</strong>：</p><ul><li>当前量子硬件仍处于“含噪声中等规模量子（NISQ）”阶段，能力有限</li><li>理论优势的证明尚不完善，实际应用尚需突破</li><li>量子纠错、量子比特相干时间等技术瓶颈有待解决</li></ul><h2 id="人工智能伦理与治理" tabindex="-1">人工智能伦理与治理 <a class="header-anchor" href="#人工智能伦理与治理" aria-label="Permalink to “人工智能伦理与治理”">​</a></h2><p>人工智能技术的快速发展带来了深刻的<strong>社会伦理</strong>问题，需要建立健全的治理体系，确保人工智能向善发展。</p><p><strong>核心伦理问题</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>算法偏见与公平性</strong></td><td style="text-align:left;">训练数据中的历史偏见可能被算法放大，导致种族、性别歧视等</td></tr><tr><td style="text-align:left;"><strong>隐私保护</strong></td><td style="text-align:left;">数据收集使用过程中侵犯个人隐私（如人脸识别滥用）</td></tr><tr><td style="text-align:left;"><strong>可解释性</strong></td><td style="text-align:left;">深度学习模型的“黑箱”特性使其决策过程难以向用户解释</td></tr><tr><td style="text-align:left;"><strong>责任归属</strong></td><td style="text-align:left;">自动驾驶、医疗AI等高风险场景下的决策责任归属</td></tr><tr><td style="text-align:left;"><strong>就业冲击</strong></td><td style="text-align:left;">自动化可能取代大量传统岗位，带来结构性失业</td></tr><tr><td style="text-align:left;"><strong>安全与失控风险</strong></td><td style="text-align:left;">恶意利用AI（如深度伪造）或AGI潜在的对人类的目标偏离风险</td></tr></tbody></table><p><strong>治理框架与原则</strong>：</p><ul><li>联合国教科文组织《人工智能伦理建议书》：提出AI发展应遵循比例原则、公平原则、透明与可解释性原则</li><li>中国《新一代人工智能治理原则》强调 <strong>“发展负责任的人工智能”</strong> ，倡导公平公正、安全可控、尊重隐私</li><li>欧盟《人工智能法案》采用基于风险的分级监管框架</li></ul><h2 id="人工智能算法开发框架" tabindex="-1">人工智能算法开发框架 <a class="header-anchor" href="#人工智能算法开发框架" aria-label="Permalink to “人工智能算法开发框架”">​</a></h2><p>人工智能算法开发框架为研究者与工程师提供了高效的工具平台，降低了AI应用开发的门槛，加速了从研究到产业落地的转化过程。</p><p><strong>主流框架</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">框架</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>TensorFlow</strong></td><td style="text-align:left;">Google开发，生态完善，支持从训练到部署的全流程，拥有强大的分布式与端侧推理（TFLite）能力</td></tr><tr><td style="text-align:left;"><strong>PyTorch</strong></td><td style="text-align:left;">Meta开发，动态计算图，易用性强，在学术界占据主导，研究到生产过渡顺畅</td></tr><tr><td style="text-align:left;"><strong>PaddlePaddle</strong></td><td style="text-align:left;">百度开发，国产框架代表，中文文档丰富，产业应用案例广泛</td></tr><tr><td style="text-align:left;"><strong>MindSpore</strong></td><td style="text-align:left;">华为开发，支持端边云全场景协同，与大模型训练和自动并行能力深度结合</td></tr><tr><td style="text-align:left;"><strong>JAX</strong></td><td style="text-align:left;">Google开发，面向函数编程，提供自动微分，支持高效数值计算与模型研究</td></tr></tbody></table><p><strong>框架提供的核心能力</strong>：</p><ul><li>自动微分与梯度计算，简化复杂模型训练</li><li>丰富的预置层、算子与预训练模型库，提升开发效率</li><li>分布式并行训练支持，适应超大模型训练</li><li>模型优化与跨平台部署工具链，缩短推理环节</li></ul><h2 id="小结-1" tabindex="-1">小结 <a class="header-anchor" href="#小结-1" aria-label="Permalink to “小结”">​</a></h2><ul><li><strong>类脑计算</strong>从大脑结构中汲取灵感，探索更高效的计算范式</li><li><strong>自动化机器学习</strong>降低AI使用门槛，提升模型开发效率</li><li><strong>神经网络压缩</strong>使大模型能运行在终端设备上</li><li><strong>AI芯片</strong>为人工智能应用提供强大的算力支撑</li><li><strong>量子机器学习</strong>探索量子计算与人工智能融合的远景可能</li><li><strong>人工智能伦理与治理</strong>确保技术发展符合人类价值观</li><li><strong>AI算法开发框架</strong>连接研究与应用，推动生态繁荣</li></ul><p>人工智能的发展正处于由弱人工智能向通用人工智能迈进的过程中，机遇与挑战并存。</p>',69)),e(x),e(f)])}const B=h(y,[["render",P]]);export{G as __pageData,B as default};
